function initialGraph(){
  const nodes=[],edges=[],seen=new Set();
  function add(n){if(!seen.has(n.id)){seen.add(n.id);nodes.push(n);}return n.id;}
  function edge(source,target){edges.push({source,target,type:"CONTAINS",confidence:"EXTRACTED"});}
  for(const s of [...snapshots,{repo:"exams-app-archive",sha:"",paths:catalog.map(x=>x[0])}]){
    const root=add({id:"repo:"+s.repo,label:s.repo,repo:s.repo,type:"Repo",path:"",sha:s.sha});
    for(const path of s.paths){const dir=path.includes("/")?path.split("/")[0]:"root";const folderId="dir:"+s.repo+":"+dir;const isNew=!seen.has(folderId);add({id:folderId,label:dir,repo:s.repo,type:"Directory",path:dir,sha:s.sha});if(isNew)edge(root,folderId);
      const id=add({id:"file:"+s.repo+":"+path,label:path.split("/").pop(),repo:s.repo,path,sha:s.sha,type:/\.(tsx|jsx)$/.test(path)?"Component":/\.md$/.test(path)?"Document":/\.(png|jpe?g|webp|gif|svg)$/i.test(path)?"Image":"File",publicUrl:"https://github.com/ianmaciel7/"+s.repo+"/blob/"+(s.sha||"main")+"/"+path.split("/").map(encodeURIComponent).join("/")});edge(folderId,id);
    }
  }
  return {nodes,edges};
}
graphData=initialGraph();
const descriptions=new Map(catalog);
state.records=graphData.nodes.map(n=>({repository:n.repo,kind:"node",sourceType:n.type,sha:n.sha,path:n.path,summary:descriptions.get(n.path)||n.label,graphId:n.id,publicUrl:n.publicUrl,publicPath:n.repo==="exams-app-archive"&&descriptions.has(n.path)?n.path:undefined}));
$("dataset").textContent="Catálogo público · "+snapshots.reduce((n,s)=>n+s.paths.length,0).toLocaleString("pt-BR")+" arquivos";
state.loaded=true;updateFilters();const initialQuery=new URLSearchParams(location.search).get("q");if(initialQuery)$("query").value=initialQuery.slice(0,200);filter();
